window.RP_SESSION={"id":"S-7f040204bf06","messages":[{"id":"RP-0175294","time":"2026-06-19T20:00:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"마침 개와 늑대와 멍청한 퐉스의 시간.","characters":["P-55e987e3c831"]},{"id":"RP-0175295","time":"2026-06-19T20:00:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"저 멀리 덫에 잡혀있는 아쎄이가 개인지 늑대인지 여우인지 구분이 잘 안가는 때 입니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175296","time":"2026-06-19T20:01:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"왜 그런진 몰라도 여우 덫을 놓기에 좋다고 하더라고요. 군데 군데 야생동물의 흔적이 보이는 곳에 간간이 판자형 여우 덫을 박으며 등산을 하고 있습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175297","time":"2026-06-19T20:03:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"판자를 잡고 부드러운 흙 아래로 콱 콱 박아요.","characters":["P-55e987e3c831"]},{"id":"RP-0175298","time":"2026-06-19T20:03:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그리고 가운데 꼬챙이 부분에 생고기를 꽂아줍니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175299","time":"2026-06-19T20:04:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"참을 수 없겠지? 와서 한 입 베어물고 싶겠지?\"","characters":["P-55e987e3c831"]},{"id":"RP-0175300","time":"2026-06-19T20:05:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"흥얼거리면서 산을 타고 있어요.","characters":["P-55e987e3c831"]},{"id":"RP-0175301","time":"2026-06-19T20:06:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"@발락","characters":["P-55e987e3c831"]},{"id":"RP-0175302","time":"2026-06-19T20:06:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"SAY MY NAME","characters":["P-55e987e3c831"]},{"id":"RP-0175304","time":"2026-06-20T00:31:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이어하실거면 말해주세욧","characters":["P-55e987e3c831"]},{"id":"RP-0175305","time":"2026-06-20T00:31:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-55e987e3c831"]},{"id":"RP-0175308","time":"2026-06-20T20:34:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"오늘도 평화로운 어용 어용 어용 대장간 말고 다른 걸 합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175309","time":"2026-06-20T20:34:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"어제 설치해둔 여우 덫을 확인하러 와요.","characters":["P-55e987e3c831"]},{"id":"RP-0175310","time":"2026-06-20T20:34:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-55e987e3c831"]},{"id":"RP-0175311","time":"2026-06-20T20:34:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 12 = 12\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0175312","time":"2026-06-20T20:35:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"산의 초입, 가장 먼저 설치한 덫을 확인하자마자 여우 아쎄이을 발견해버렸습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175313","time":"2026-06-20T20:35:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"음...\"","characters":["P-55e987e3c831"]},{"id":"RP-0175314","time":"2026-06-20T20:36:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-55e987e3c831"]},{"id":"RP-0175315","time":"2026-06-20T20:37:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"대충 이런 꼴로 잡혀서 낑낑거리는 여우를 보고 잠깐 각을 재고요.","characters":["P-55e987e3c831"]},{"id":"RP-0175316","time":"2026-06-20T20:37:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"뚝배기 상단을 향해 창대를 날립니다. 가죽을 최대한 보존하려면 날을 쓰면 안돼요.","characters":["P-55e987e3c831"]},{"id":"RP-0175317","time":"2026-06-20T20:37:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-55e987e3c831"]},{"id":"RP-0175318","time":"2026-06-20T20:37:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'브랜'의 힘 판정 :\n[12] + [2] = [14]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0175319","time":"2026-06-20T20:37:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"한방에 절명시켰쮸","characters":["P-55e987e3c831"]},{"id":"RP-0175320","time":"2026-06-20T20:39:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"여우를 덫에서 집어올리고, 뒷다리의 아킬레스건 부위에 구멍을 냅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175321","time":"2026-06-20T20:40:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그대로 창대에 꿰어서 어깨에 거꾸로 짊어진 다음 산을 내려와요. 어용 어용 어용 태너리.","characters":["P-55e987e3c831"]},{"id":"RP-0175322","time":"2026-06-20T20:44:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"대장간 앞 강으로 돌아와서, 대충 나뭇가지들로 지지대를 세운 다음, 여우 목의 경동맥을 베어 피를 빼둡니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175323","time":"2026-06-20T20:45:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그 동안 지난번 강 앞에서 끓여둔 나무껍질 물을 나무통에 바가지로 옮겨담습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175324","time":"2026-06-20T20:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"아, 이거 여우는 털을 남겨야 되는데 그러면 이걸 못 쓰네.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175325","time":"2026-06-20T20:47:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"여우 가죽은 풍성한 꼬리가 모피에 딸려 있어야 제일 좋아요.","characters":["P-55e987e3c831"]},{"id":"RP-0175326","time":"2026-06-20T20:48:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"피가 빠진 여우 가죽을 벗기기 시작합니다.\n꼬리 아래쪽을 조심스럽게 박피용 단검으로 절개한 뒤, 한쪽 뒷발목 안쪽에서 시작해서 사타구니 사이를 지나쳐, 반대쪽 뒷발목 안쪽까지 칼집을 내어 연결해요.","characters":["P-55e987e3c831"]},{"id":"RP-0175327","time":"2026-06-20T20:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그렇게 꼬리의 시작되는 부분 뼈를 강하게 움켜잡고 아래로 잡아당겨, 꼬리 가죽은 그대로 둔 채 내부의 꼬리뼈만 쏙 빼냅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175328","time":"2026-06-20T20:52:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이제 가죽을 머리 방향으로 쓸어내리며 벗깁니다. 가죽과 근육 사이의 조직을 밀어내며 분리하고, 질긴 부분은 박피용 단검으로 살짝 째어줘요.","characters":["P-55e987e3c831"]},{"id":"RP-0175329","time":"2026-06-20T20:53:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"앞다리, 얼굴부분은 형상이 복잡하니 더욱 세심한 손길로 벗겨줍니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175330","time":"2026-06-20T20:55:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"가죽을 완전히 벗겨냈지만 여전히 가죽 안쪽에 지방이나 살점 등이 남아있습니다. 둥근 그루터기 위에 가죽을 뒤집어 씌워놓아요.","characters":["P-55e987e3c831"]},{"id":"RP-0175331","time":"2026-06-20T20:56:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그 옆에서 여우의 남은 살을 처리합니다. 낚시용 미끼로 써도 좋겠군요.","characters":["P-55e987e3c831"]},{"id":"RP-0175332","time":"2026-06-20T20:57:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"일단 다음 작업엔 여우의 뇌가 쓰입니다. 모든 동물의 뇌엔 각각의 가죽을 무두질 할 수 있는 분량의 뇌가 있다고 하니 절묘하죠.","characters":["P-55e987e3c831"]},{"id":"RP-0175333","time":"2026-06-20T20:58:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"여우의 뇌를 지난번 나무껍질을 끓일 때 썼던 솥에 담고, 물을 부은 뒤 끓입니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175334","time":"2026-06-20T20:59:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그 동안 양쪽에 손잡이가 달린 드로우나이프처럼 생긴 긁개를 사용해, 뒤집어둔 여우 가죽을 위에서 아래로 밀어내며 살점과 지방을 깨끗하게 긁어냅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175335","time":"2026-06-20T21:02:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그러고 물을 양동이로 부워 긁어낸 잔여물을 씻어내고, 솥에서 회백색 수프처럼 된 것을 양동이에 담아다가 강물에 통째로 담가 식힙니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175336","time":"2026-06-20T21:03:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그걸 여우 가죽 안쪽에 발라 침투시킵니다. 골고루 바르고 문질러 스며들게 해요.","characters":["P-55e987e3c831"]},{"id":"RP-0175337","time":"2026-06-20T21:05:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"가죽이 스프를 흡수할 시간이 필요하니, 통나무 그루터기에 펼쳐놓고 마르게 둡니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175338","time":"2026-06-20T21:08:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그러면 다시 여우 속살로 돌아와서, 고기를 쓰기 좋게 썰고 지방을 분리하죠. 솥에 우물물을 부워 씻어내고 모아둔 지방을 넣어요. 약간의 물을 더해 지방을 녹이죠.","characters":["P-55e987e3c831"]},{"id":"RP-0175339","time":"2026-06-20T21:09:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다시 솥에 불을 지피고 휘저어가며 물에 지방을 녹여냅니다. 돼지였으면 라드가 됐을텐데 이건 가죽 장비를 부드럽게 만드는 윤활유로나 써야겠군요.","characters":["P-55e987e3c831"]},{"id":"RP-0175340","time":"2026-06-20T21:10:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"미끼통에 여우고기와 내장등을 담습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175341","time":"2026-06-20T21:26:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"브랜이 기본적인 가죽 가공을 하는 동안… 쩍, 쩍. 어디선가 나무 패는 소리가 들려왔습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0175342","time":"2026-06-20T21:27:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그런데 사람의 손으로 하는 게 맞는 건지, 그 박자감이 요상하게 들려옵니다.","characters":["P-c93f55c91873"]},{"id":"RP-0175343","time":"2026-06-20T21:30:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"역시나 그 발원지는 촉수! 2수 1조로 도끼를 든 6개의 가닥을 등에 매단 델타인이 옆구리에 장작을 끼고 다가왔습니다.\n\n\"오, 피 냄새 향긋한 저녁이네요!\"\n\n브랜이 오다가다 잡일만 주구장창 하는 델타인을 알아봤을지는 모르겠지만… 델타인은 그러든 말든 인사를 건넸습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0175344","time":"2026-06-20T21:38:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다시 돌아온 어용 어용 어용 대장간... 인데 누군가 있네요.","characters":["P-55e987e3c831"]},{"id":"RP-0175345","time":"2026-06-20T21:39:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"안녕하세요. 엄, 좋은 저녁입니다.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175346","time":"2026-06-20T21:39:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"전 브랜이고요. 예.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175347","time":"2026-06-20T21:40:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"슬쩍 도끼를 쥔 촉수들을 보고 놀랍니다. \"그거 장작 패는 속도가 엄청나겠네요.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175348","time":"2026-06-20T21:41:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"맞아요, 브랜드. 전 델타인이에요. 데루타닌이나 델타윈이 아니니 발음에 주의하세요!\"","characters":["P-c93f55c91873"]},{"id":"RP-0175349","time":"2026-06-20T21:42:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"델타룬 끼야아악호","characters":["P-55e987e3c831"]},{"id":"RP-0175350","time":"2026-06-20T21:43:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"예, 델타인... 고생 많으십니다. 그 장작은 어디 쓰십니까?\"","characters":["P-55e987e3c831"]},{"id":"RP-0175351","time":"2026-06-20T21:44:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그거야 길드 사람들이 쓰죠! 제혁 중이셨어요? 신기하다. 여기서 이런 걸 하는 사람은 두 명 밖에 못 봤어요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0175352","time":"2026-06-20T21:44:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그렇게 말하곤 솥에 물과 양피지를 넣고 끓여서 부드럽게 만듭니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175353","time":"2026-06-20T21:45:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"두명이나 있었군요. 그, 사실 저는 여기선 소일거리로 할까 하다가 뭔가 점점 늘어났어요.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175354","time":"2026-06-20T21:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"뭔가 내면의 깨달음이니 뭐니 하는 걸 말하려다가 스스로 생각해도 개소리인 거 같아서 참습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175355","time":"2026-06-20T21:46:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 브왁 씨를 포함해서 둘이에요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0175356","time":"2026-06-20T21:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그으렇군요. 근데 브왁씨요?\"","characters":["P-55e987e3c831"]},{"id":"RP-0175357","time":"2026-06-20T21:47:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"기억을 천천히 되짚어봅니다. 모르는 이름인데...","characters":["P-55e987e3c831"]},{"id":"RP-0175358","time":"2026-06-20T21:48:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"방금 브왁 씨라고 그러셨잖아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0175359","time":"2026-06-20T21:48:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"도리도리 \"아뇨, 아뇨. 브랜입니다. 브랜.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175360","time":"2026-06-20T21:48:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 어깨를 으쓱해보였다. \n\n\"네, 브라?\"","characters":["P-c93f55c91873"]},{"id":"RP-0175361","time":"2026-06-20T21:48:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이 발음이 맞나요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0175362","time":"2026-06-20T21:49:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"도리도리 \"브ㅡ랜요. 브 랜.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175363","time":"2026-06-20T21:49:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"브랜드 할 때 처럼요.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175364","time":"2026-06-20T21:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"살짝 물에 데쳐져서 흐물해진 가죽을 집게로 꺼냅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175365","time":"2026-06-20T21:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"공기중에 살짝 식히고, 리넨천으로 물기를 제거하죠.","characters":["P-55e987e3c831"]},{"id":"RP-0175366","time":"2026-06-20T21:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"브, 브, 브으, 프, 프랑.\"\n\n촉수들에게서 하나둘 도끼를 회수하고, 굵기가 균일한 장작들을 한아름 모아 등에 매었습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0175367","time":"2026-06-20T21:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이름이란 게 참 어렵네요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0175368","time":"2026-06-20T21:53:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"뭐어, 그렇긴 하죠.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175369","time":"2026-06-20T21:53:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그런 양피지를 자신의 안면 하단부터, 목을 지나 쇄골까지 덮어 씁니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175370","time":"2026-06-20T21:54:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"옷핀으로 접히는 곳을 고정하고, 끈으로 묶어 형상을 고정해요. 유아들이 쓰는 턱받침 처럼요.","characters":["P-55e987e3c831"]},{"id":"RP-0175371","time":"2026-06-20T21:55:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"근처 숯가마 내부에서 남아있던 숯조각을 하나 집어들어, 그대로 갑옷으로 만들 부위를 선으로 그어 본을 뜹니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175372","time":"2026-06-20T21:55:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"목과 턱과 쇄골같이 곡선이 많아 어려운 부위는 치수를 이렇게 따는 게 나아요.","characters":["P-55e987e3c831"]},{"id":"RP-0175373","time":"2026-06-20T21:56:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그렇게 양피지에 패턴 마킹을 하고, 끈을 푼 뒤 펼쳐봅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175374","time":"2026-06-20T21:56:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그 장작은 요리에 쓰는 거였나요?\"","characters":["P-55e987e3c831"]},{"id":"RP-0175375","time":"2026-06-20T21:59:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"요리에도 쓰고, 모닥불에도 쓰고, 무슨 실험에도 필요하대요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0175376","time":"2026-06-20T22:00:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"많이 쓰이는군요.\" 주억거립니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175377","time":"2026-06-20T22:03:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"엄, 전 이제 대장간으로 가볼게요. 쓸만한 철이 들어왔는데 갑옷 부위 중 하나를 만들까 하거든요.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175378","time":"2026-06-20T22:03:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"와, 그렇죠? 장작을 쓰는 사람은 많은데 장작을 패는 사람은 얼마 없단 말이죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-0175379","time":"2026-06-20T22:04:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"저도 그냥 나무 해다가 쓰고 그랬죠 뭐...\"","characters":["P-55e987e3c831"]},{"id":"RP-0175380","time":"2026-06-20T22:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"요즘 들어 사람을 장작으로 만드는 마법을 만들고 싶어지더라고요.\"\n\n델타인이 회수한 도끼 중 하나를 장난스럽게 한차례 휘둘렀습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0175381","time":"2026-06-20T22:05:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그런 마법이 정말 있습니까?!\"","characters":["P-55e987e3c831"]},{"id":"RP-0175382","time":"2026-06-20T22:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"나무로 만들어서 팔 부분만 자르고 정령술을 쓸 줄 아는 분이 재생시킨 뒤에 다시 사람으로 만들면 편할 것 같지 않나요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0175383","time":"2026-06-20T22:06:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그러고는 도끼를 내려놓습니다.\n\n\"아쉽게도 없죠. 제가 연구해서 만들려고요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0175384","time":"2026-06-20T22:06:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그건...\"","characters":["P-55e987e3c831"]},{"id":"RP-0175385","time":"2026-06-20T22:06:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"'기괴한데요.'라는 말을 꾹 참습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175386","time":"2026-06-20T22:07:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"엄, 행운을 빕니다. 저라면 그냥 나무를 자르겠지만요.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175387","time":"2026-06-20T22:07:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"생각해보세요. 그런 마법이 널리 퍼지면 추운 곳에 사는 사람들도 따뜻하게 지낼 수 있잖아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0175388","time":"2026-06-20T22:07:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그으...렇죠?\"","characters":["P-55e987e3c831"]},{"id":"RP-0175389","time":"2026-06-20T22:09:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이야, 프랑 씨는 말이 잘 통하네요.\"\n\n브랜을 향해 빵긋 웃어보이는 델타인. 뿌듯하다는 표정입니다.","characters":["P-c93f55c91873"]},{"id":"RP-0175390","time":"2026-06-20T22:09:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c93f55c91873"]},{"id":"RP-0175391","time":"2026-06-20T22:10:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그, 제 이름은 풍악입니다.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175392","time":"2026-06-20T22:10:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"뭐 프랑도 좋고요.\"\n메시지가 삭제되었습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175393","time":"2026-06-20T22:10:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"부왁이라구요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0175394","time":"2026-06-20T22:10:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"마음속으로 이마를 탁 칩니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175395","time":"2026-06-20T22:10:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"프랑요. 하하.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175396","time":"2026-06-20T22:12:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그럼 뿌앙 씨, 저도 이만 가볼게요. 청소도 하고 설거지도 해야 하거든요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0175397","time":"2026-06-20T22:12:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"할 일이 많으시군요.\" 끄덕여보입니다. \"다음에 뵙지요.\"","characters":["P-55e987e3c831"]},{"id":"RP-0175398","time":"2026-06-20T22:14:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다시 돌아온 평화롭지 않은 어용 어용 어용 대장간","characters":["P-55e987e3c831"]},{"id":"RP-0175399","time":"2026-06-20T22:15:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"방금 일어났던 일은 깊게 생각하지 않고, 대장간으로 돌아와 작업대에 양피지를 펼칩니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175400","time":"2026-06-20T22:15:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"옷핀을 풀고, 넓게 좍 펼친 뒤 옷핀에 가려져서 끊긴 부분을 목탄으로 마저 선으로 스윽 스윽 이어줍니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175401","time":"2026-06-20T22:17:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그걸 재단용 가위로 잘라줍니다. 만들 것은 비버라는 판금 방어구. 안면 하단, 목, 쇄골 부분을 보호하는 갑옷입니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175402","time":"2026-06-20T22:18:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"목을 감싸는 가운데 칼라 부분과, 턱과 입을 가리는 부분으로 나눈 뒤 그림 외곽선을 따라 재단용 가위로 잘라줍니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175403","time":"2026-06-20T22:22:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"미리 만들어둔 강철판 위에 패턴을 대고 목탄으로 외곽선을 그어요.","characters":["P-55e987e3c831"]},{"id":"RP-0175404","time":"2026-06-20T22:23:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"강철판도 녹이지 않고 단조와 풀림 작업으로 펴낸 것이라 표면은 울퉁불퉁 합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175405","time":"2026-06-20T22:24:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그은 외곽선을 따라 펀치로 마킹합니다. 펀치를 철판에 대고 망치로 때려서 움푹 패인 선을 긋는 것이예요.","characters":["P-55e987e3c831"]},{"id":"RP-0175406","time":"2026-06-20T22:25:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"화로에 불을 지피고, 불타는 숯에 강철판을 파묻은 다음 풀무질을 힘차게 합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175407","time":"2026-06-20T22:25:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"화로의 온도는 일단 올려놓는데, 철판은 오랜지 색으로 빛날 때 우선 꺼내요.","characters":["P-55e987e3c831"]},{"id":"RP-0175408","time":"2026-06-20T22:26:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그리고 한쪽 끝에 손잡이가 달린 판금 가위로 철판을 자릅니다. 사무용 가위처럼 가볍게 쓰는 가위가 아니라 커다란 작두처럼 생긴 물건이예요.","characters":["P-55e987e3c831"]},{"id":"RP-0175409","time":"2026-06-20T22:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이제 모루의 네모난 하디 홀에 성형용 봉모루를 꽂습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175410","time":"2026-06-20T22:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다시 판금을 화로에서 달구고, 노란색이 되면 빼낸 뒤 철솔로 숯가루같은 불순물을 털어냅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175411","time":"2026-06-20T22:30:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그럴때마다 불똥이 예쁘게 반짝거리며 흩날려요.","characters":["P-55e987e3c831"]},{"id":"RP-0175412","time":"2026-06-20T22:30:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이 작업을 하기 전에, 두꺼운 대장장이용 앞치마와 장갑은 꼭 착용합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175413","time":"2026-06-20T22:31:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"하여튼 가열한 철판을 둥근 봉모루에 대고 망치로 두드려가며 목에서 쇄골로 이어지는 곡선에 맞게 굽힙니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175414","time":"2026-06-20T22:32:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"한동안 계속 작업을 하죠. 턱받이 판도 만드는데, 중간중간 식을 때마다","characters":["P-55e987e3c831"]},{"id":"RP-0175415","time":"2026-06-20T22:33:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"두꺼운 갬비슨 천이나 가죽을 목쪽에 두르고 한번씩 작업물을 대봐서 치수가 맞는지 확인하죠.","characters":["P-55e987e3c831"]},{"id":"RP-0175416","time":"2026-06-20T22:33:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"힘내는 것은 제가 아닌 브랜이니 열심히 구릅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175417","time":"2026-06-20T22:33:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-55e987e3c831"]},{"id":"RP-0175418","time":"2026-06-20T22:33:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'브랜'의 힘 판정 :\n[10] + [2] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0175419","time":"2026-06-20T22:34:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"브랜은 다이나믹한 로동을 하게 두고 저는 잠깐 콜라나 마시면서 유튜브 봅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175420","time":"2026-06-20T22:38:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!모닥불","characters":["P-55e987e3c831"]},{"id":"RP-0175421","time":"2026-06-20T22:38:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]},{"id":"RP-0175422","time":"2026-06-20T23:17:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"갑옷의 형태가 잡혀갑니다. 날카로운 철판 끝 부분은 둥글게 접어올립니다. 착용자에게 상처를 주는 걸 방지하는 한편, 미끄러진 무기의 칼날을 막아내는 턱 역할도 해요.","characters":["P-55e987e3c831"]},{"id":"RP-0175423","time":"2026-06-20T23:24:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이제 열처리 작업으로 들어가기 전, 최종 풀림 작업을 해줍니다. 화로에서 따뜻한 재들을 따로 쇠갈퀴로 빼내어 앞에 둔 다음, 작업물을 칙칙한 빨강색이 될 때까지 화로에서 달궈요.","characters":["P-55e987e3c831"]},{"id":"RP-0175424","time":"2026-06-20T23:25:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이제 화로에 다른 재를 덮어 끄고, 따로 빼 둔 재 속에 작업물을 묻고 하루동안 천천히 식힐 예정입니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175425","time":"2026-06-20T23:26:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다시 대장간 앞으로 나와, 잠깐 물을 마시며 숨을 돌립니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175426","time":"2026-06-20T23:27:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이제 준비됐을 여우 가죽 앞의 그루터기에 털썩 앉아서, 나뭇가지로 여우 가죽을 올릴 거치대를 만들죠.","characters":["P-55e987e3c831"]},{"id":"RP-0175427","time":"2026-06-20T23:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"별 건 없고 대충 낮은 원뿔 모양처럼 생겼습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175428","time":"2026-06-20T23:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그러고 나서 토막난 통나무 한쪽 끝에 여우가죽의 안쪽 면을 비벼요.","characters":["P-55e987e3c831"]},{"id":"RP-0175429","time":"2026-06-20T23:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"하얗게 될 정도로 문질러서 부드럽게 만들어줍니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175430","time":"2026-06-20T23:30:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그럼 이제 나무틀 안에 목공 작업으로 생긴 톱밥을 작은 화로 안에 채워넣고 불을 붙여요.","characters":["P-55e987e3c831"]},{"id":"RP-0175431","time":"2026-06-20T23:30:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그 위에 여우가죽을 뒤집어 씌워서 훈제시킵니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175432","time":"2026-06-20T23:30:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!모닥불","characters":["P-55e987e3c831"]},{"id":"RP-0175433","time":"2026-06-20T23:30:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]},{"id":"RP-0175434","time":"2026-06-20T23:30:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이제 불을 쬐며 물도 마시고 쉽니다.","characters":["P-55e987e3c831"]},{"id":"RP-0175435","time":"2026-06-20T23:31:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-55e987e3c831"]},{"id":"RP-0175436","time":"2026-06-20T23:31:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]},{"id":"RP-0177437","time":"2026-06-21T20:38:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"대장간에 들어서서 문과 창문을 열어 환기시킵니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177438","time":"2026-06-21T20:39:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"두꺼운 소가죽으로 만들어진 앞치마와 장갑을 끼고요.","characters":["P-55e987e3c831"]},{"id":"RP-0177439","time":"2026-06-21T20:40:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"어제부터 따뜻한 재 속에 하루종일 파묻어놓은 작업물을 집게도 꺼내듭니다. 철솔로 재를 털어내죠.","characters":["P-55e987e3c831"]},{"id":"RP-0177440","time":"2026-06-21T20:40:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"화로에 숯을 넣고 불을 지핍니다. 작업물을 화로 안에 넣고, 풀무질을 해요.","characters":["P-55e987e3c831"]},{"id":"RP-0177441","time":"2026-06-21T20:42:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"퀜칭 텁 옆에 물을 받아놓은 통을 같이 둡니다. 이제 작업물에 구멍을 뚫으려고 하는데, 직접 닿는 펀치를 차갑게 유지해야 돼서요.","characters":["P-55e987e3c831"]},{"id":"RP-0177442","time":"2026-06-21T20:43:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 열린 대장간 문","characters":["P-3ea4affc20fd"]},{"id":"RP-0177443","time":"2026-06-21T20:43:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"똑똑똑똑.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177444","time":"2026-06-21T20:43:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"모루엔 움푹 파인 구멍이 있는데, 그 위에 밝은 오랜지 빛으로 달군 작업물을 올려놓습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177445","time":"2026-06-21T20:43:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"히히 혼극 방해다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177446","time":"2026-06-21T20:43:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그리고 정처럼 생긴... 펀치를 올려놓고 때리려는 찰나, 인기척에 문쪽을 돌아보죠.","characters":["P-55e987e3c831"]},{"id":"RP-0177447","time":"2026-06-21T20:43:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"누구십니까?\"","characters":["P-55e987e3c831"]},{"id":"RP-0177448","time":"2026-06-21T20:44:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"어라, 신입인가?\"\n\n 전에 있던 놈들은 어디갔는지 원. 지팡이 짚은 사제 한명이 들어옵니다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177449","time":"2026-06-21T20:45:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"예, 브랜입니다. 좋은 저녁이군요.\"","characters":["P-55e987e3c831"]},{"id":"RP-0177450","time":"2026-06-21T20:45:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"나는 사이먼이라고 하네. 좋은 저녁.\"","characters":["P-3ea4affc20fd"]},{"id":"RP-0177451","time":"2026-06-21T20:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"끄덕이곤, 펀치를 물에 다시 담그고 달궈진 목부분 갑옷에 놓은다음 망치로 때립니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177452","time":"2026-06-21T20:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"한번 칠 때마다 움푹 파이더니, 구멍이 뚫리죠. 안감 고정용 구멍과, 호흡용 구멍을 목부위 가장자리에 뚫습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177453","time":"2026-06-21T20:46:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"뜨거울 때 때려야 해서요. 무슨 일로 오셨지요?\"","characters":["P-55e987e3c831"]},{"id":"RP-0177454","time":"2026-06-21T20:47:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아차. 할 이야기 있었지.\n\n \"내 칼이 이가 빠져서...\"\n\n 사이먼이 지팡이를 분리해 그 안의 칼날을 보여준다. 확실히 이가 나갔다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177455","time":"2026-06-21T20:47:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"오... 지팡이 검이군요.\"","characters":["P-55e987e3c831"]},{"id":"RP-0177456","time":"2026-06-21T20:48:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 한 달 전에 나갔던 놈인데 다른거 쓰다가 잊어먹었지.\n\n \"그래. 내 몸이 이래가.\"\n\n 왼쪽 다리가 다른 쪽 보다 짧으니 지팡이 없이 걷기 힘들다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177457","time":"2026-06-21T20:49:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"부탁할 수 있겠나?\"","characters":["P-3ea4affc20fd"]},{"id":"RP-0177458","time":"2026-06-21T20:49:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"엄청나군요.\" 그럼 구멍을 뚫는다는 목적은 이뤘으니, 식어가는 작업물은 오랜지 빛으로 다시 달구고 퀜칭텁에 식힙니다","characters":["P-55e987e3c831"]},{"id":"RP-0177459","time":"2026-06-21T20:49:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"집게로 잡고 기름이 담긴 통에 담궈서 열처리를 하는 것이죠. 치이익 하고 빠르게 식혀요.","characters":["P-55e987e3c831"]},{"id":"RP-0177460","time":"2026-06-21T20:49:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그리고 화로 앞에 잠깐 둡니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177461","time":"2026-06-21T20:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"물론입니다.\"","characters":["P-55e987e3c831"]},{"id":"RP-0177462","time":"2026-06-21T20:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"열처리로 생긴 응력은 다시 화로 앞에서 풀라고 두고...","characters":["P-55e987e3c831"]},{"id":"RP-0177463","time":"2026-06-21T20:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"사이먼의 검을 받아들죠.","characters":["P-55e987e3c831"]},{"id":"RP-0177464","time":"2026-06-21T20:51:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그리고 날 상태를 자세히 봅니다. \"이만 상했으니 좀 갈면 되겠는데요?\"","characters":["P-55e987e3c831"]},{"id":"RP-0177465","time":"2026-06-21T20:51:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그렇겠지.\"\n\n 끄덕슨.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177466","time":"2026-06-21T20:52:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그걸 들고 페달형 사암 그라인더 앞에 앉습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177467","time":"2026-06-21T20:52:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 할 것도 없으니 기다립니다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177468","time":"2026-06-21T20:52:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"발로 페달을 밟아 돌리더니, 평평한 그라인더 위에 밀착시켜 갈아내기 시작해요.","characters":["P-55e987e3c831"]},{"id":"RP-0177469","time":"2026-06-21T20:52:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" ...\n\n '아이고 무릎이야...'\n\n 앉아서 기다립니다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177470","time":"2026-06-21T20:53:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그에 따라 반짝이는 불똥이 회전 방향으로 마구 튑니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177471","time":"2026-06-21T20:54:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"잠깐 동안의 거친 대형 숫돌질이 끝나면, 이제 고정된 숫돌판 위로 가져갑니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177472","time":"2026-06-21T20:55:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"물을 그 위에 좀 뿌리고, 검날을 숫돌 위에서 왕복하며 문지르죠.","characters":["P-55e987e3c831"]},{"id":"RP-0177473","time":"2026-06-21T20:56:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그런 작업을 중간중간 검날을 확인하면서 진행하고, 점점 고운 숫돌로 바꿔가며 합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177474","time":"2026-06-21T20:57:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"오 전문가.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177475","time":"2026-06-21T20:57:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이제 숫돌 바퀴에 소가죽을 씌우고, 아마씨유를 바른 뒤 아주 고운 모래를 뿌려요.","characters":["P-55e987e3c831"]},{"id":"RP-0177476","time":"2026-06-21T20:58:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다시 페달을 밟아 첫번째 작업과 비슷하게 검을 대는데, 이번엔 갈지 않고 광택만 냅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177477","time":"2026-06-21T20:59:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다 끝났으면 연마 과정에서 묻은 기름과 연마제 가루들을 리넨 천으로 깨끗하게 닦죠.","characters":["P-55e987e3c831"]},{"id":"RP-0177478","time":"2026-06-21T21:00:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"리넨 천을 감싸쥔 왼손 위에 검날을 올려놓고, 날 상태를 전체적으로 훑어보더니 사이먼에게 수평으로 내밉니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177479","time":"2026-06-21T21:00:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"다 됐습니다.\"","characters":["P-55e987e3c831"]},{"id":"RP-0177480","time":"2026-06-21T21:02:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 비틀비틀 넘어지지 않게 조심히 걸어가 지팡이칼을 받아든다.\n\n \"정말 고맙네.\"\n\n 칼을 검집에 넣어 다시 지팡이처럼 만든 후 짚는다.\n\n \"수고비는 얼마면 되나?\"","characters":["P-3ea4affc20fd"]},{"id":"RP-0177481","time":"2026-06-21T21:02:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"그건 됐습니다. 어처피 소일거리니까요.\"","characters":["P-55e987e3c831"]},{"id":"RP-0177482","time":"2026-06-21T21:03:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"손을 내젓습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177483","time":"2026-06-21T21:03:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 헉.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177484","time":"2026-06-21T21:03:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"재료들도 제가 산 게 아니고, 대장간도 빌려 쓰는 건데요 뭘. 그냥 장부에만 적어놓겠습니다.\"","characters":["P-55e987e3c831"]},{"id":"RP-0177485","time":"2026-06-21T21:04:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 사이먼은 소매넣기을/(를) 시전했다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177486","time":"2026-06-21T21:04:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"실링과 알사탕 몇개를 브랜의 손에 꼭꼭 쥐어주련다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0177487","time":"2026-06-21T21:05:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"엄... 그럼 감사히 받겠습니다.\" 바로 알사탕 하나를 입에 넣어요.","characters":["P-55e987e3c831"]},{"id":"RP-0177488","time":"2026-06-21T21:06:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 흐뭇하다.\n\n \"그럼 나중에 또봅세. 고마웠네.\"","characters":["P-3ea4affc20fd"]},{"id":"RP-0177489","time":"2026-06-21T21:06:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"안☆녕","characters":["P-3ea4affc20fd"]},{"id":"RP-0177490","time":"2026-06-21T21:07:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"예, 살펴가십쇼.\" 사이먼에게 인사하고 잠깐 가죽부대에서 물을 마십니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177491","time":"2026-06-21T21:11:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다시 낮은 온도로 뜨임이 들어간 목 갑옷 작업물을 집게로 집어듭니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177492","time":"2026-06-21T21:13:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"가공 과정에서 발생한 망치 자국을 평평한 연마용 망치로 약하게 두드려 자국만 좀 없애고","characters":["P-55e987e3c831"]},{"id":"RP-0177493","time":"2026-06-21T21:14:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"페달형 그라인더로 갈아 표면에 스크래치를 남깁니다. 광택을 잘 내기보단 역으로 죽일건데요.","characters":["P-55e987e3c831"]},{"id":"RP-0177494","time":"2026-06-21T21:15:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"퀜칭텁의 아마씨유를 작업물 표면에 바른 뒤 화로 안에서 앞의 받침으로 불타는 숯을 좀 끄집어냅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177495","time":"2026-06-21T21:15:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그 상태로 구워서 검은 보호층을 만들어줘요.","characters":["P-55e987e3c831"]},{"id":"RP-0177496","time":"2026-06-21T21:15:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"이제 공기중에 잠시 꺼내놓아 식힌 뒤, 리넨 천으로 말끔히 닦습니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177497","time":"2026-06-21T21:17:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"비버 갑옷 안쪽에 직물로 만든 패딩을 덧대고, 비버 가장자리의 구멍 몇개에 꿰매어 고정합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177498","time":"2026-06-21T21:19:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"거기에 목 뒤로 둘러 고정하는 가죽끈과 버클도 리벳으로 연결하죠. 가죽끈에 펀치로 구멍을 내고, 아까 비버에 미리 뚫었던 리벳용 구멍에 맞춘 뒤 핀형 리벳을 끼웁니다. 망치로 두들겨서 단단히 물려놓죠.","characters":["P-55e987e3c831"]},{"id":"RP-0177499","time":"2026-06-21T21:27:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"직접 만든 비버(Bevor) 갑옷을 한번 착용해봅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0177500","time":"2026-06-21T21:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"...오잉?! 브랜의 상태가...!","characters":["P-55e987e3c831"]},{"id":"RP-0177501","time":"2026-06-21T21:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-55e987e3c831"]},{"id":"RP-0177502","time":"2026-06-21T21:28:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"축하합니다! 브랜은 2렙으로 진화했다!","characters":["P-55e987e3c831"]},{"id":"RP-0177503","time":"2026-06-21T21:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"ㅋㅋ 화로의 불을 끄고 대장간은 열기가 빠지도록 환기 상태는 유지합니다. 문 밖으로 나가서 밤공기를 쐬며 물을 마시죠.","characters":["P-55e987e3c831"]},{"id":"RP-0177504","time":"2026-06-21T21:29:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-55e987e3c831"]},{"id":"RP-0177505","time":"2026-06-21T21:29:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]},{"id":"RP-0177506","time":"2026-06-21T21:36:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"https://www.youtube.com/watch?v=KF0gxUd9CZA","characters":["P-55e987e3c831"]}]};
